import{z as A,x as l,o as r,c as d,q as o,j as i,D as e,d as E,s as B,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"影子银行挤兑","description":"","frontmatter":{"title":"影子银行挤兑","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/shadow-run.md","filePath":"econ/shadow-run.md","lastUpdated":1791063341000}'),p={name:"econ/shadow-run.md"};function h(c,a,D,u,C,m){const n=l("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="影子银行挤兑" tabindex="-1">影子银行挤兑 <a class="header-anchor" href="#影子银行挤兑" aria-label="Permalink to &quot;影子银行挤兑&quot;">​</a></h1><div class="epigraph"><p>不受存款保险覆盖的短债，一样可以挤兑。2008 年停的是 ABCP、回购和货币市场基金份额，不只是柜面排队。</p><footer>—— Gorton and Metrick, Securitized Banking and the Run on Repo, JFE 2012；Covitz, Liang and Suarez 的 ABCP 挤兑</footer></div><p><a href="/econ/banking-crises-history">上一课</a>把模式钉在信贷与短债上。缺口是：许多短债不在银行牌照里。本课钉影子挤兑；央行表下一课才讲谁来买这些资产。不重写 DD 的存款合约，也不重走<a href="/econ/shadow-banking">影子银行</a>课的链路记账——这里要的是挤兑现场与它的证据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>影子银行用证券化、回购、ABCP 把长期资产做成「信息不敏感」的短债（Gorton）。haircut 或展期一旦跳升，等同挤兑：不是取现金，是不再续作。2007–08 的 ABCP 与回购是这一机制的现场。Covitz, Liang and Suarez 把 ABCP 的死法分了阶段：先是发行量萎缩、展期期限越滚越短，管道靠发起银行的支持线度日；2007 年 8 月资产方坏消息一到，续作集体撤出，1.2 万亿美元量级的市场一年之内缩去三成。若模型里只有受保存款，会把危机写成「监管没覆盖的边角」，而不是核心滚动市场。</p><p>Gorton and Metrick 的证据链是一条时间序列：向交易商收集证券化抵押品的回购 haircut，合成一个「影子银行系统」指数。2007 年初，AAA 证券化券的隔夜回购 haircut 接近零——一分抵押借一分钱；从当年 12 月起大约每季翻倍，2008 年底平均到 45% 附近。同一笔融资要压近一倍的抵押进去，等于债权人集体抽走一半滚动负债。指数走低先于投资下滑，这是「挤兑」的价格记法：柜面上没有排队，账本上全是。</p><p><span class="marginnote">Pozsar 等人的影子银行地图：链上每一环都在做期限或流动性转换。Krishnamurthy, Nagel and Orlov 的回购：三方市场以国债与代理 MBS 为主、危机中大体照常滚动，挤兑集中在双边证券化回购——「回购崩了」要说清是哪一层。Run on repo 的定量大小有争论，机制仍是 haircut 与停滚。</span></p><p><span class="marginnote">数字实例：Gorton–Metrick 的测量里，AAA 证券化券的隔夜回购 haircut 从 2007 年初的近零升到 2008 年底的约 45%——原来 1 亿元券能借 1 亿元，现在只能借 5500 万元；同样的负债要压近一倍的抵押，等于债权人集体抽走一半滚动额度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把影子负债当成与存款同类的需求：安全、短期、可转手。挤兑触发：资产信息变敏感、haircut 上升、MMF 跌破 \\(1。政策：流动性工具扩到一级交易商与 CP，等于把最后贷款人边界外推。宏观：\\)\\phi$ 约束突然收紧，与 GK 的净值冲击同向——中介能杠杆的资产集变小，溢价与产出一起动。</p>',10)),(r(),i(s,null,{default:e(()=>[B(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E9%95%BF%E6%9C%9F%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20ST%5B%22ABCP%20%2F%20%E5%9B%9E%E8%B4%AD%22%5D%0A%20%20ST%20--%3E%20INS%5B%22%E4%BF%A1%E6%81%AF%E4%B8%8D%E6%95%8F%E6%84%9F%E7%9F%AD%E5%80%BA%22%5D%0A%20%20NEWS%5B%22%E4%BF%A1%E6%81%AF%E5%8F%98%E6%95%8F%E6%84%9F%22%5D%20--%3E%20HC%5B%22haircut%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20HC%20--%3E%20RUN%5B%22%E5%81%9C%E6%BB%9A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"信息不敏感债在好状态下不需要尽调，所以便宜；坏状态一开始，所有人都要尽调，市场冻结（Dang–Gorton–Holmström）。关键在信息获取是策略互补的：没人收集信息时，一家独查是白花钱，债权照面值易手，「无知」是设计出来的公共品；一旦有人开始查，不查的那位就在接别人挑剩的资产，于是尽调集体爆发。对称的无知一破，交易对手再分不清谁手里是金子谁手里是雷，市场停摆。危机的定义因此不是坏消息本身，而是「无知时代的终结」。",-1)),(r(),i(s,null,{default:e(()=>[B(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOOD%5B%22%E5%A5%BD%E7%8A%B6%E6%80%81%3A%20%E5%80%BA%E6%9D%83%E4%BF%A1%E6%81%AF%E4%B8%8D%E6%95%8F%E6%84%9F%22%5D%20--%3E%20NOCHECK%5B%22%E6%97%A0%E4%BA%BA%E5%B0%BD%E8%B0%83%2C%20%E6%8C%89%E9%9D%A2%E5%80%BC%E4%BA%A4%E6%98%93%22%5D%0A%20%20NEWS%5B%22%E8%B5%84%E4%BA%A7%E7%AB%AF%E5%9D%8F%E6%B6%88%E6%81%AF%22%5D%20--%3E%20FIRST%5B%22%E6%9C%89%E4%BA%BA%E5%BC%80%E5%A7%8B%E5%B0%BD%E8%B0%83%22%5D%0A%20%20FIRST%20--%3E%20FEAR%5B%22%E4%B8%8D%E6%9F%A5%E7%9A%84%E4%BA%BA%E5%8F%AA%E8%83%BD%E6%8E%A5%E6%8C%91%E5%89%A9%E7%9A%84%E8%B5%84%E4%BA%A7%22%5D%0A%20%20FEAR%20--%3E%20ALLCHECK%5B%22%E5%B0%BD%E8%B0%83%E9%9B%86%E4%BD%93%E7%88%86%E5%8F%91%22%5D%0A%20%20ALLCHECK%20--%3E%20OPAQUE%5B%22%E5%88%86%E4%B8%8D%E6%B8%85%E8%B0%81%E6%8C%81%E9%87%91%E5%AD%90%E8%B0%81%E6%8C%81%E9%9B%B7%22%5D%0A%20%20OPAQUE%20--%3E%20FREEZE%5B%22%E6%8B%92%E7%BB%9D%E7%BB%AD%E4%BD%9C%2C%20%E5%B8%82%E5%9C%BA%E5%81%9C%E6%91%86%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">术语翻译：「信息不敏感」就是「不打开看也知道值多少」的债——像密封包装的标准件，大家不拆检就按面值买卖，交易才便宜。它不是天然属性，是被 haircut、担保与声誉刻意设计出来的状态。</span></p><p>haircut 是抵押品风险的价格，跳升就是挤兑税。它与存款挤兑的差别在合同、不在逻辑：存款是序贯服务加存款保险，挤兑表现成柜面排队，保险把坏均衡删掉；回购是抵押加续作，挤兑表现成抵押率抬升与拒绝续作，债权人是识货的对家而不是储户，而且没有现成的保险与便利。挤兑因此更安静也更快：一封不续作的邮件，抵得上一个营业日的排队。这也解释政策为何要现造工具——一级交易商不是银行，贴现窗本来对它不开放；PDCF、AMLF、CPFF 是临时改写<a href="/econ/lender-of-last-resort">最后贷款人</a>的资格表。</p><p><span class="marginnote">常见误区：初学者容易把「雷曼倒闭」当挤兑的起点。实际上双边回购的 haircut 从 2007 年 8 月已开始收紧、12 月起每季翻倍——起点是抵押品信息变敏感，雷曼只是把不确定性钉死。把因果读反，会误判政策介入的时间窗口。</span></p><p><span class="marginnote">haircut 的跳升先于 Lehman：2007 年 8 月起双边回购已在收紧，雷曼之后是全面的数量配给。把「雷曼倒闭」当起点会读反因果：起点是抵押品信息变敏感，雷曼只是把不确定性钉死。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有非银都是影子银行。保险公司长期负债不是同一挤兑：债权不可按面值日赎，挤兑要走退保价值与再融资渠道换算。影子挤兑也不等于「回购市场整体崩塌」：国债端照常滚动，崩的是证券化抵押那一层。下一课看央行如何用资产负债表承接停滚后的资产。不写 2010 年后每一条 SEC MMF 改革细则。</p><p>后课默认：「挤兑」一词同时用在存款与批发债上，指的都是同一件事——短期债权在坏状态被集体拒绝续作；宏观模型里它是 \\(\\phi\\) 的离散跳变，不再只是 DD 的提款队列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>影子挤兑是停滚与 haircut，不是柜面。</li><li>Gorton–Metrick：haircut 从近零到 45%、每季翻倍，是挤兑的价格记法。</li><li>信息不敏感短债在坏状态下集体尽调，市场冻结；「无知」是设计，不是运气。</li><li>与存款挤兑差在合同：序贯服务与保险对抵押与续作，挤兑税与政策工具都随之换形。</li><li>出处：Gorton and Metrick, <em>JFE</em> 2012；Covitz, Liang and Suarez 的 ABCP；Dang–Gorton–Holmström。</li></ul>',9))])}const _=A(p,[["render",h]]);export{f as __pageData,_ as default};
